for a in z['actions']:s.step(a)
s.painter.finish();strokes=s.strokes(); t=cv2.imread('/app/target.png',0)<120
n,l,stats,_=cv2.connectedComponentsWithStats(t.astype(np.uint8),8)
records=[]
for ss in strokes:
 r,c=ss['mask_bbox'];m=ss['mask']>=128; pred=np.zeros_like(t);pred[r:r+m.shape[0],c:c+m.shape[1]]=m
 ys,xs=np.where(pred);pc=(xs.mean(),ys.mean());i=min(range(1,n),key=lambda i:abs(pc[0]-(stats[i,0]+stats[i,2]/2))+abs(pc[1]-(stats[i,1]+stats[i,3]/2)))
 x,y,w,h,a=stats[i]; truth=np.zeros_like(t);truth[y:y+h,x:x+w]=l[y:y+h,x:x+w]==i
 records.append((pred,truth,(x,y,w,h),i))
# Baseline / fit separate axis scales and translation (2-pixel grid)
for pred,truth,box,i in records:
 x,y,w,h=box; cx=x+w/2;cy=y+h/2
 crop=(slice(max(0,y-12),min(1024,y+h+12)),slice(max(0,x-12),min(1024,x+w+12)))
 best=(0,None);base=0
 for sx in [1.0]:
  for sy in [1.0]:
   for dx in [0]:
    for dy in [0]:
     M=np.array([[sx,0,cx*(1-sx)+dx],[0,sy,cy*(1-sy)+dy]],np.float32)
     q=cv2.warpAffine(pred.astype(np.uint8),M,(1024,1024),flags=cv2.INTER_NEAREST)>0
     i0=(q&truth).sum()/((q|truth).sum());base=i0
 for sx in np.arange(.92,1.101,.02):
  for sy in np.arange(.92,1.101,.02):
   for dx in range(-3,4):
    for dy in range(-3,4):
     M=np.array([[sx,0,cx*(1-sx)+dx],[0,sy,cy*(1-sy)+dy]],np.float32)
     q=cv2.warpAffine(pred.astype(np.uint8),M,(1024,1024),flags=cv2.INTER_NEAREST)>0
     aa=q[crop];bb=truth[crop];ii=(aa&bb).sum();uu=(aa|bb).sum();v=ii/uu
     if v>best[0]:best=(v,(sx,sy,dx,dy,ii,aa.sum()))
 print('cc',i,'base',base,'best affine',best)
# Combine best per stroke transform in global raster and print combined IoU
qs=[]
for pred,truth,(x,y,w,h),i in records:
 cx=x+w/2;cy=y+h/2;best=(0,None,None)
 for sx in np.arange(.92,1.101,.02):
  for sy in np.arange(.92,1.101,.02):
   for dx in range(-3,4):
    for dy in range(-3,4):
     M=np.array([[sx,0,cx*(1-sx)+dx],[0,sy,cy*(1-sy)+dy]],np.float32)
     q=cv2.warpAffine(pred.astype(np.uint8),M,(1024,1024),flags=cv2.INTER_NEAREST)>0
     v=(q&truth).sum()/((q|truth).sum())
     if v>best[0]:best=(v,(sx,sy,dx,dy),q)
 qs.append(best[2])
pr=np.logical_or.reduce(qs);print('combined', (pr&t).sum()/ (pr|t).sum(),pr.sum(),t.sum())
